(()=>{
const words={
sqTitle:['當月統一報價單','Monthly common quotation','Cotización mensual común','Báo giá chung theo tháng'],
sqHelp:['報價依國家、年／月、幣別分開儲存，套用至同月份各授權部門。請先選年月與幣別，再輸入或匯入報價；其他月份不會變動。','Quotes are saved by country, year/month and currency and apply to departments in that month. Select month and currency before entering or importing prices; other months stay unchanged.','Las cotizaciones se guardan por país, año/mes y moneda y se aplican a ese mes. Seleccione mes y moneda antes de ingresar o importar precios; los otros meses no cambian.','Lưu báo giá theo quốc gia, năm/tháng và tiền tệ; áp dụng cho các bộ phận trong cùng tháng. Chọn tháng và tiền tệ trước khi nhập; không đổi tháng khác.'],
sqSave:['儲存當月統一報價','Save monthly common quote','Guardar cotización mensual','Lưu báo giá chung tháng'],
sqDoc:['報價單號','Quotation number','Número de cotización','Số báo giá'],
sqDate:['報價日期','Quotation date','Fecha de cotización','Ngày báo giá'],
sqSource:['匯入來源檔名','Imported filename','Archivo importado','Tên tệp nhập'],
sqTemplate:['下載當月報價範本','Download monthly quote template','Descargar plantilla mensual','Tải mẫu báo giá tháng'],
sqImport:['匯入當月報價單','Import monthly quotation','Importar cotización mensual','Nhập báo giá tháng'],
sqExport:['匯出當月報價 Excel','Export monthly quote Excel','Exportar cotización mensual Excel','Xuất Excel báo giá tháng'],
sqPreview:['報價匯入預覽（確認後仍須儲存）','Quote import preview (save after applying)','Vista previa de cotización (guarde tras aplicar)','Xem trước báo giá (cần lưu sau khi áp dụng)'],
sqImportHelp:['使用範本的「報價資料」工作表，年月份（YYYY-MM）與幣別須符合目前選擇。單價可填 0，最多四位小數；空白表示未報價。未列於匯入檔的既有項目會保留。','Use the 報價資料 template sheet. Month (YYYY-MM) and currency must match the selection. Prices allow zero and up to four decimals; blank means unquoted. Existing items omitted from the file are retained.','Use la hoja 報價資料. Mes (YYYY-MM) y moneda deben coincidir. Precio cero permitido, hasta cuatro decimales; vacío significa sin cotizar. Se conservan los ítems no incluidos.','Dùng trang 報價資料. Tháng (YYYY-MM) và tiền tệ phải khớp. Giá có thể bằng 0, tối đa bốn số thập phân; trống là chưa báo giá. Giữ các mục không có trong tệp.'],
sqReadOnly:['統一報價由管理員維護；主管可查看與匯出。','Administrators maintain common quotes; supervisors can view and export.','Administradores editan; supervisores pueden ver y exportar.','Quản trị viên cập nhật; quản lý có thể xem và xuất.'],
sqBefore:['目前單價','Current price','Precio actual','Đơn giá hiện tại'],sqAfter:['匯入單價','Imported price','Precio importado','Đơn giá nhập'],
sqError_currency:['幣別與目前選擇不同。','Currency differs from the selection.','La moneda no coincide.','Tiền tệ không khớp.'],
sqError_metadata:['報價廠商、單號、日期或備註不一致。請每次匯入一份報價單。','Conflicting vendor, number, date or notes. Import one quotation at a time.','Proveedor, número, fecha o notas no coinciden. Importe una cotización a la vez.','Nhà cung cấp, số, ngày hoặc ghi chú không thống nhất. Nhập từng báo giá.'],
sqError_date:['報價日期須為所選月份的有效日期（YYYY-MM-DD）。','Quotation date must be a valid date in the selected month (YYYY-MM-DD).','Fecha válida del mes seleccionado (YYYY-MM-DD).','Ngày báo giá hợp lệ trong tháng đang chọn (YYYY-MM-DD).'],
sqInvalid:['請檢查報廢項目、單價及報價日期。','Check items, prices and quotation date.','Revise ítems, precios y fecha.','Kiểm tra loại, đơn giá và ngày báo giá.'],
sqFile:['請使用 10 MB 以下的 Excel 或 CSV，Excel 須含「報價資料」工作表，且不可包含公式。','Use Excel or CSV under 10 MB. Excel must contain 報價資料 with no formulas.','Use Excel o CSV de menos de 10 MB; hoja 報價資料 sin fórmulas.','Dùng Excel hoặc CSV dưới 10 MB; trang 報價資料 không chứa công thức.']
};for(const[k,v]of Object.entries(words))translations[k]=Object.fromEntries(['zh','en','es','vi'].map((l,i)=>[l,v[i]]));
const defaults=['鐵屑','鐵粒','鐵花','製程報廢','調機品','鐵皮/鐵牌/鐵線','廠商下腳料','白鐵','鋁合金','製程下腳料','S10設備製程報廢'],currencies=['TWD','VND','MXN','USD','EUR','CNY','JPY'];
let ctx=null,sheet=null,currency='',scope='',generation=0,editing=false,saving=false;
const copy=x=>structuredClone(x),label=k=>txt(k),el=s=>document.querySelector(s),els=s=>[...document.querySelectorAll(s)];
function setDirty(){editing=true;ctx.dirty(true);el('#scPrint').disabled=true;el('#scMessage').innerHTML=txt('scDraft');}
function table(){return `<div class="sc-scroll"><table class="sc-table"><thead><tr><th>${label('scItem')}</th><th>${label('scPrice')} (${esc(currency)}/kg)</th></tr></thead><tbody>${sheet.quotes.map((q,i)=>`<tr><td><input class="select" data-sq-item="${i}" value="${esc(q.item)}" maxlength="100" ${ctx.admin&&!q.saved?'':'readonly'}></td><td><input class="select" data-sq-price="${i}" value="${q.price??''}" type="number" min="0" max="1000000" step="0.0001" ${ctx.admin?'':'readonly'}></td></tr>`).join('')}</tbody></table></div>`;}
function render(){if(!ctx?.root.isConnected||!sheet)return;const ro=ctx.admin?'':'readonly';ctx.root.innerHTML=`<article class="sc-paper sc-quote-sheet"><h2>${ctx.month} ${label('sqTitle')}</h2><p>${label('sqHelp')}</p>${ctx.admin?'':`<p class="notice">${label('sqReadOnly')}</p>`}<div class="sc-meta"><label>${label('scCurrency')}<select id="sqCurrency" class="select">${currencies.map(c=>`<option ${c===currency?'selected':''}>${c}</option>`).join('')}</select></label>${[['vendor','scVendor'],['document_no','sqDoc'],['quote_date','sqDate'],['note','scNote']].map(([f,k])=>`<label>${label(k)}<input class="select" data-sq-meta="${f}" value="${esc(sheet.details[f]||'')}" ${f==='quote_date'?`type="date" min="${ctx.month}-01" max="${ctx.month}-${new Date(Number(ctx.month.slice(0,4)),Number(ctx.month.slice(5)),0).getDate()}"`:'maxlength="2000"'} ${ro}></label>`).join('')}</div>${sheet.details.source_filename?`<p>${label('sqSource')}：${esc(sheet.details.source_filename)}</p>`:''}${table()}<div class="filter-row">${ctx.admin?`<button id="sqAdd" class="btn secondary">${label('scAddItem')}</button><button id="sqSave" class="btn primary">${label('sqSave')}</button><button id="sqTemplate" class="btn secondary">${label('sqTemplate')}</button><button id="sqImport" class="btn secondary">${label('sqImport')}</button><input id="sqFile" type="file" accept=".xlsx,.xls,.csv" hidden>`:''}<button id="sqExport" class="btn secondary">${label('sqExport')}</button></div><p class="notice">${label('sqImportHelp')}</p><div id="sqPreview" aria-live="polite"></div></article>`;
 el('#sqCurrency').onchange=e=>{if(!ctx.leave()){e.target.value=currency;return;}currency=e.target.value;ctx.dirty(false);editing=false;load();};
 els('[data-sq-meta]').forEach(e=>e.oninput=()=>{sheet.details[e.dataset.sqMeta]=e.value;setDirty();});
 els('[data-sq-price]').forEach(e=>e.oninput=()=>{sheet.quotes[+e.dataset.sqPrice].price=e.value===''?null:Number(e.value);setDirty();});
 els('[data-sq-item]').forEach(e=>e.oninput=()=>{sheet.quotes[+e.dataset.sqItem].item=e.value;setDirty();});
 el('#sqAdd')?.addEventListener('click',()=>{if(sheet.quotes.length>=100)return;sheet.quotes.push({item:'',price:null});setDirty();render();els('[data-sq-item]').at(-1).focus();});
 el('#sqSave')?.addEventListener('click',save);el('#sqTemplate')?.addEventListener('click',()=>exportFile(true));el('#sqExport').onclick=()=>exportFile(false);
 el('#sqImport')?.addEventListener('click',()=>el('#sqFile').click());el('#sqFile')?.addEventListener('change',importFile);
}
async function load(){const g=++generation,c=ctx,cur=currency;sheet=null;c.root.innerHTML=txt('cadreLoading');el('#scExport').disabled=true;try{const r=await api({action:'scrap_quotes_get',month:c.month,currency:cur});if(g!==generation||!c.root.isConnected)return;sheet=copy(r.sheet);sheet.details||={};sheet.quotes=sheet.quotes.map(q=>({...q,saved:true}));for(const item of defaults)if(!sheet.quotes.some(q=>q.item===item))sheet.quotes.push({item,price:null});editing=false;c.dirty(false);render();el('#scExport').disabled=false;el('#scMessage').innerHTML=txt(sheet.revision?'scSaved':'scEmpty');}catch{if(g===generation&&c.root.isConnected)c.root.innerHTML=txt('scFailed');}}
function valid(){const result=ScrapQuoteImport.parse([ScrapQuoteImport.columns,...sheet.quotes.map(q=>[ctx.month,currency,q.item,q.price??'',sheet.details.vendor||'',sheet.details.document_no||'',sheet.details.quote_date||'',sheet.details.note||''])],{month:ctx.month,currency});return !result.errors.length&&sheet.quotes.length<=100&&new Set(sheet.quotes.map(q=>q.item.trim())).size===sheet.quotes.length;}
async function save(){if(saving||!ctx.admin||!sheet)return;if(!valid()){el('#scMessage').innerHTML=txt('sqInvalid');return;}const c=ctx,g=generation;saving=true;c.busy(true);const disabled=els('.scrap-page button,.scrap-page input,.scrap-page select,#primaryLanguage,#secondaryLanguage').map(e=>[e,e.disabled]);disabled.forEach(([e])=>e.disabled=true);try{const r=await api({action:'scrap_quotes_save',month:c.month,currency,revision:sheet.revision,quotes:sheet.quotes.map(q=>({item:q.item.trim(),price:q.price})),details:sheet.details});if(g!==generation||!c.root.isConnected)return;sheet=copy(r.sheet);sheet.quotes=sheet.quotes.map(q=>({...q,saved:true}));editing=false;c.dirty(false);c.saved();render();el('#scMessage').innerHTML=txt('scSaved');}catch(e){if(c.root.isConnected)el('#scMessage').innerHTML=txt(e.message.includes('record_changed')?'scConflict':'scFailed');}finally{saving=false;c.busy(false);disabled.forEach(([e,d])=>{if(e.isConnected)e.disabled=d;});}}
function exportFile(template=false){if(!sheet||typeof XLSX==='undefined')return;const rows=[ScrapQuoteImport.columns,...(template?defaults.map(item=>({item,price:null})):sheet.quotes).map(q=>[ctx.month,currency,q.item,q.price??'',template?'':sheet.details.vendor||'',template?'':sheet.details.document_no||'',template?'':sheet.details.quote_date||'',template?'':sheet.details.note||''])];const w=XLSX.utils.book_new(),s=XLSX.utils.aoa_to_sheet(rows);s['!cols']=[12,10,25,16,30,22,16,48].map(wch=>({wch}));s['!autofilter']={ref:`A1:H${rows.length}`};for(let r=1;r<rows.length;r++)if(s[`D${r+1}`]?.t==='n')s[`D${r+1}`].z='0.0000';XLSX.utils.book_append_sheet(w,s,'報價資料');XLSX.writeFile(w,`${template?'報價匯入範本':'統一報價單'}-${activeCountry}-${ctx.month}-${currency}${!template&&editing?'-未儲存草稿':''}.xlsx`);}
async function importFile(e){const file=e.target.files?.[0];e.target.value='';if(!file||!ctx.admin||saving||!sheet)return;const c=ctx,g=generation,stamp=JSON.stringify(sheet),container=el('#sqPreview');const fail=k=>{if(container.isConnected)container.innerHTML=`<p class="notice">${txt(k)}</p>`;};if(file.size>10*1024*1024||! /\.(xlsx|xls|csv)$/i.test(file.name))return fail('sqFile');try{const bytes=await file.arrayBuffer();if(g!==generation||!container.isConnected||stamp!==JSON.stringify(sheet))return;const wb=XLSX.read(bytes,{type:'array',raw:true}),ws=wb.Sheets['報價資料']||(/\.csv$/i.test(file.name)?wb.Sheets[wb.SheetNames[0]]:null);if(!ws)return fail('sqFile');const range=XLSX.utils.decode_range(ws['!ref']||'A1');if(range.e.r>1000||range.e.c>30||Object.values(ws).some(v=>v?.f))return fail('sqFile');const result=ScrapQuoteImport.parse(XLSX.utils.sheet_to_json(ws,{header:1,defval:'',raw:true}),{month:c.month,currency});const merged=copy(sheet.quotes);for(const q of result.quotes||[]){const old=merged.find(x=>x.item===q.item);if(old)old.price=q.price;else merged.push(q);}if(merged.length>100)result.errors.push({row:0,code:'limit'});if(result.errors.length){container.innerHTML=`<p>${txt('scImportError')}</p><ul>${result.errors.slice(0,50).map(x=>`<li>${txt('scImportRow')} ${x.row||'—'}：${txt(['currency','metadata','date'].includes(x.code)?'sqError_'+x.code:'scImport_'+x.code)}</li>`).join('')}</ul>`;return;}container.innerHTML=`<h3>${txt('sqPreview')}</h3><p>${c.month} · ${esc(currency)} · ${esc(file.name)}</p><p>${esc(Object.values(result.details).join(' · '))}</p><div class="sc-scroll"><table class="sc-table"><thead><tr><th>${txt('scItem')}</th><th>${txt('sqBefore')}</th><th>${txt('sqAfter')}</th></tr></thead><tbody>${result.quotes.map(q=>`<tr><td>${esc(q.item)}</td><td>${sheet.quotes.find(x=>x.item===q.item)?.price??t('scPending')}</td><td>${q.price??t('scPending')}</td></tr>`).join('')}</tbody></table></div><button id="sqApply" class="btn primary">${txt('scImportApply')}</button> <button id="sqCancel" class="btn secondary">${txt('scImportCancel')}</button>`;el('#sqCancel').onclick=()=>container.replaceChildren();el('#sqApply').onclick=()=>{if(g!==generation||stamp!==JSON.stringify(sheet)||saving)return fail('scConflict');sheet.quotes=merged;sheet.details={...sheet.details,...result.details,source_filename:file.name};setDirty();render();};}catch{fail('sqFile');}}
window.ScrapQuotes={mount(c){const next=[activeCountry,c.month,profile.account_id,profile.role].join(':');ctx=c;if(scope!==next){scope=next;currency={TW:'TWD',VM:'VND',MX:'MXN'}[activeCountry];sheet=null;}if(!sheet||!editing||!c.preserve)load();else render();},exportData:()=>exportFile(false)};
})();
